package es.gestionsolicitudes.salud.aplicacion;

/** Puerto técnico que no expone detalles de conexión a la capa HTTP. */
public interface ComprobacionBaseDatos {
    boolean disponible();
}

package es.gestionsolicitudes.salud.aplicacion;

public enum EstadoSalud {
    DISPONIBLE,
    NO_DISPONIBLE
}

package es.gestionsolicitudes.salud.aplicacion;

import org.springframework.stereotype.Service;

@Service
public class ServicioSalud {
    private final ComprobacionBaseDatos baseDatos;

    public ServicioSalud(ComprobacionBaseDatos baseDatos) {
        this.baseDatos = baseDatos;
    }

    public EstadoSalud comprobar() {
        return baseDatos.disponible() ? EstadoSalud.DISPONIBLE : EstadoSalud.NO_DISPONIBLE;
    }
}

package es.gestionsolicitudes.salud.http;

import es.gestionsolicitudes.salud.aplicacion.EstadoSalud;
import es.gestionsolicitudes.salud.aplicacion.ServicioSalud;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.media.Content;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.responses.ApiResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class ControladorSalud {
    private final ServicioSalud servicio;

    public ControladorSalud(ServicioSalud servicio) {
        this.servicio = servicio;
    }

    @Operation(summary = "Consultar disponibilidad técnica", description = "No acredita funciones de negocio.")
    @ApiResponse(responseCode = "200", description = "Aplicación y PostgreSQL disponibles",
            content = @Content(schema = @Schema(implementation = RespuestaSalud.class)))
    @ApiResponse(responseCode = "503", description = "Dependencia temporalmente no disponible",
            content = @Content(schema = @Schema(implementation = RespuestaSalud.class)))
    @GetMapping(value = "/api/salud", produces = "application/json")
    public ResponseEntity<RespuestaSalud> consultar() {
        var estado = servicio.comprobar();
        var codigo = estado == EstadoSalud.DISPONIBLE ? HttpStatus.OK : HttpStatus.SERVICE_UNAVAILABLE;
        return ResponseEntity.status(codigo).body(new RespuestaSalud(estado));
    }
}

package es.gestionsolicitudes.salud.http;

import es.gestionsolicitudes.salud.aplicacion.EstadoSalud;
import io.swagger.v3.oas.annotations.media.Schema;

@Schema(description = "Disponibilidad técnica de la aplicación y PostgreSQL")
public record RespuestaSalud(
        @Schema(requiredMode = Schema.RequiredMode.REQUIRED) EstadoSalud estado) {}

package es.gestionsolicitudes.salud.persistencia;

import es.gestionsolicitudes.salud.aplicacion.ComprobacionBaseDatos;
import java.sql.SQLException;
import javax.sql.DataSource;
import org.springframework.stereotype.Repository;

@Repository
public class ComprobacionPostgres implements ComprobacionBaseDatos {
    private final DataSource dataSource;

    public ComprobacionPostgres(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    @Override
    public boolean disponible() {
        try (var conexion = dataSource.getConnection();
                var consulta = conexion.prepareStatement("SELECT 1")) {
            consulta.setQueryTimeout(2);
            try (var resultado = consulta.executeQuery()) {
                return resultado.next() && resultado.getInt(1) == 1;
            }
        } catch (SQLException falloDependencia) {
            // El estado público no incluye mensajes del driver, SQL ni configuración.
            return false;
        }
    }
}

package es.gestionsolicitudes.integracion;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import es.gestionsolicitudes.GestionSolicitudesApplication;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.time.Duration;
import java.util.Map;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.testcontainers.utility.DockerImageName;
import tools.jackson.databind.json.JsonMapper;

class BaseVerificableIT {
    private static final String IMAGEN =
            "postgres:17.11-bookworm@sha256:3645570cccdfa447589da9f57dd740faa29b30938e861289a5574b6ca6b03826";

    private PostgreSQLContainer contenedor() {
        return new PostgreSQLContainer(DockerImageName.parse(IMAGEN).asCompatibleSubstituteFor("postgres"))
                .withDatabaseName("gestion")
                .withUsername("administrador_prueba")
                .withPassword("administracion-ficticia-prueba")
                .withInitScript("postgres-inicial.sql");
    }

    private ConfigurableApplicationContext arrancar(PostgreSQLContainer base, String... opciones) {
        return new SpringApplicationBuilder(GestionSolicitudesApplication.class)
                .properties(Map.of(
                        "DB_URL", base.getJdbcUrl(),
                        "DB_USUARIO", "gestion_app",
                        "DB_CLAVE", "aplicacion-ficticia-prueba",
                        "MIGRACION_USUARIO", "gestion_migracion",
                        "MIGRACION_CLAVE", "migracion-ficticia-prueba",
                        "spring.main.banner-mode", "off"))
                .run(opciones);
    }

    private HttpResponse<String> consultar(HttpClient cliente, ConfigurableApplicationContext contexto, String ruta) throws Exception {
        String puerto = contexto.getEnvironment().getRequiredProperty("local.server.port");
        return cliente.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:" + puerto + ruta))
                .timeout(Duration.ofSeconds(10)).GET().build(), HttpResponse.BodyHandlers.ofString());
    }

    @Test
    void primerArranqueContratoPermisosYSegundoArranque() throws Exception {
        try (var base = contenedor(); var cliente = HttpClient.newHttpClient()) {
            base.start();
            try (var contexto = arrancar(base, "--server.port=0")) {
                var salud = consultar(cliente, contexto, "/api/salud");
                assertThat(salud.statusCode()).isEqualTo(200);
                assertThat(salud.body()).isEqualTo("{\"estado\":\"DISPONIBLE\"}");
                assertThat(contexto.getBean(Flyway.class).info().applied()).hasSize(1);
                var contrato = consultar(cliente, contexto, "/v3/api-docs");
                assertThat(contrato.statusCode()).isEqualTo(200);
                var json = JsonMapper.builder().build().readTree(contrato.body());
                assertThat(json.path("openapi").asString()).startsWith("3.1.");
                var respuestas = json.path("paths").path("/api/salud").path("get").path("responses");
                assertThat(respuestas.has("200")).isTrue();
                assertThat(respuestas.has("503")).isTrue();
                assertThat(json.path("paths").size()).isEqualTo(1);
                assertThat(json.path("components").path("schemas").path("RespuestaSalud").path("properties").has("estado")).isTrue();
                assertThat(consultar(cliente, contexto, "/swagger-ui/index.html").statusCode()).isEqualTo(200);
                assertThat(consultar(cliente, contexto, "/actuator/env").statusCode()).isEqualTo(403);
                comprobarPermisos(base);
            }
            // Mismo PostgreSQL y volumen del contenedor: se conserva el historial.
            try (var segundo = arrancar(base, "--server.port=0")) {
                assertThat(segundo.getBean(Flyway.class).info().applied()).hasSize(1);
                assertThat(segundo.getBean(Flyway.class).migrate().migrationsExecuted).isZero();
                assertThat(consultar(cliente, segundo, "/api/salud").statusCode()).isEqualTo(200);
            }
        }
    }

    private void comprobarPermisos(PostgreSQLContainer base) throws SQLException {
        try (var conexion = DriverManager.getConnection(base.getJdbcUrl(), "gestion_app", "aplicacion-ficticia-prueba");
                var sentencia = conexion.createStatement()) {
            assertThatThrownBy(() -> sentencia.execute("CREATE TABLE gestion.no_permitida (id integer)"))
                    .isInstanceOf(SQLException.class).satisfies(error -> assertThat(((SQLException) error).getSQLState()).isEqualTo("42501"));
            assertThatThrownBy(() -> sentencia.executeQuery("SELECT * FROM gestion.flyway_schema_history"))
                    .isInstanceOf(SQLException.class);
            assertThatThrownBy(() -> sentencia.execute("CREATE ROLE no_permitido"))
                    .isInstanceOf(SQLException.class);
        }
        try (var conexion = DriverManager.getConnection(base.getJdbcUrl(), base.getUsername(), base.getPassword());
                var sentencia = conexion.createStatement();
                var resultado = sentencia.executeQuery("SELECT tablename FROM pg_tables WHERE schemaname = 'gestion'")) {
            assertThat(resultado.next()).isTrue();
            assertThat(resultado.getString(1)).isEqualTo("flyway_schema_history");
            assertThat(resultado.next()).isFalse();
        }
    }

    @Test
    void unaMigracionInvalidaImpideElArranqueSinAlterarOtraBase() {
        try (var base = contenedor()) {
            base.start();
            assertThatThrownBy(() -> {
                try (var ignorado = arrancar(base, "--server.port=0",
                        "--spring.flyway.locations=classpath:db/migration,classpath:db/invalida")) {
                    throw new AssertionError("Una migración inválida no debe permitir el arranque");
                }
            }).isInstanceOf(org.springframework.beans.BeansException.class);
            // Una nueva aplicación con ubicaciones válidas se recupera del rollback de PostgreSQL.
            try (var contexto = arrancar(base, "--server.port=0")) {
                assertThat(contexto.getBean(Flyway.class).info().applied()).hasSize(1);
            }
        }
    }

    @Test
    void caidaRealDePostgresDevuelve503AcotadoSinDatosInternos() throws Exception {
        try (var base = contenedor(); var cliente = HttpClient.newHttpClient()) {
            base.start();
            try (var contexto = arrancar(base, "--server.port=0")) {
                assertThat(consultar(cliente, contexto, "/api/salud").statusCode()).isEqualTo(200);
                base.stop();
                long inicio = System.nanoTime();
                var salud = consultar(cliente, contexto, "/api/salud");
                assertThat(salud.statusCode()).isEqualTo(503);
                assertThat(salud.body()).isEqualTo("{\"estado\":\"NO_DISPONIBLE\"}");
                assertThat(Duration.ofNanos(System.nanoTime() - inicio)).isLessThan(Duration.ofSeconds(8));
            }
        }
    }
}

package es.gestionsolicitudes.salud.aplicacion;

import static org.assertj.core.api.Assertions.assertThat;
import org.junit.jupiter.api.Test;

class ServicioSaludTest {
    @Test
    void informaDisponibilidadSoloSiLaDependenciaResponde() {
        assertThat(new ServicioSalud(() -> true).comprobar()).isEqualTo(EstadoSalud.DISPONIBLE);
    }

    @Test
    void informaFalloDeDependenciaSinDetallesInternos() {
        assertThat(new ServicioSalud(() -> false).comprobar()).isEqualTo(EstadoSalud.NO_DISPONIBLE);
    }
}

package es.gestionsolicitudes.salud.http;

import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import es.gestionsolicitudes.configuracion.ErroresControlados;
import es.gestionsolicitudes.configuracion.SeguridadTecnica;
import es.gestionsolicitudes.salud.aplicacion.EstadoSalud;
import es.gestionsolicitudes.salud.aplicacion.ServicioSalud;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;
import org.springframework.context.annotation.Import;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;

@WebMvcTest(ControladorSalud.class)
@Import({SeguridadTecnica.class, ErroresControlados.class})
class ControladorSaludTest {
    @Autowired MockMvc http;
    @MockitoBean ServicioSalud servicio;

    @Test
    void devuelve200ConElContratoMinimo() throws Exception {
        when(servicio.comprobar()).thenReturn(EstadoSalud.DISPONIBLE);
        http.perform(get("/api/salud")).andExpect(status().isOk())
                .andExpect(content().json("{\"estado\":\"DISPONIBLE\"}"))
                .andExpect(header().string("X-Content-Type-Options", "nosniff"));
    }

    @Test
    void devuelve503SinInformacionInterna() throws Exception {
        when(servicio.comprobar()).thenReturn(EstadoSalud.NO_DISPONIBLE);
        http.perform(get("/api/salud")).andExpect(status().isServiceUnavailable())
                .andExpect(content().string("{\"estado\":\"NO_DISPONIBLE\"}"));
    }

    @Test
    void controlaUnFalloInesperado() throws Exception {
        when(servicio.comprobar()).thenThrow(new IllegalStateException("detalle privado ficticio"));
        http.perform(get("/api/salud")).andExpect(status().isInternalServerError())
                .andExpect(content().string("{\"error\":\"ERROR_INTERNO\"}"));
    }

    @Test
    void deniegaOperacionesYRutasNoPublicas() throws Exception {
        for (var ruta : new String[] {"/actuator", "/actuator/env", "/api/proveedores", "/login"}) {
            http.perform(get(ruta)).andExpect(status().isForbidden())
                    .andExpect(content().string("{\"error\":\"ACCESO_NO_PERMITIDO\"}"));
        }
        http.perform(post("/api/salud")).andExpect(status().isForbidden());
    }

    @Test
    void noAbreCorsAUnOrigenAjeno() throws Exception {
        http.perform(options("/api/salud").header("Origin", "https://ajeno.invalid")
                        .header("Access-Control-Request-Method", "GET"))
                .andExpect(status().isForbidden())
                .andExpect(header().doesNotExist("Access-Control-Allow-Origin"));
    }
}

package es.gestionsolicitudes.salud.persistencia;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.*;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;

class ComprobacionPostgresTest {
    @Test
    void limitaLaConsultaYLiberaLosRecursos() throws SQLException {
        var origen = mock(DataSource.class);
        var conexion = mock(Connection.class);
        var consulta = mock(PreparedStatement.class);
        var resultado = mock(ResultSet.class);
        when(origen.getConnection()).thenReturn(conexion);
        when(conexion.prepareStatement("SELECT 1")).thenReturn(consulta);
        when(consulta.executeQuery()).thenReturn(resultado);
        when(resultado.next()).thenReturn(true);
        when(resultado.getInt(1)).thenReturn(1);
        assertThat(new ComprobacionPostgres(origen).disponible()).isTrue();
        verify(consulta).setQueryTimeout(2);
        verify(resultado).close();
        verify(consulta).close();
        verify(conexion).close();
    }

    @Test
    void traduceErrorDeConexionSinPropagarSuMensaje() throws SQLException {
        var origen = mock(DataSource.class);
        when(origen.getConnection()).thenThrow(new SQLException("detalle privado ficticio"));
        assertThat(new ComprobacionPostgres(origen).disponible()).isFalse();
    }

    @Test
    void rechazaConsultaFallidaYLiberaConexion() throws SQLException {
        var origen = mock(DataSource.class);
        var conexion = mock(Connection.class);
        var consulta = mock(PreparedStatement.class);
        when(origen.getConnection()).thenReturn(conexion);
        when(conexion.prepareStatement("SELECT 1")).thenReturn(consulta);
        when(consulta.executeQuery()).thenThrow(new SQLException("consulta cancelada"));
        assertThat(new ComprobacionPostgres(origen).disponible()).isFalse();
        verify(consulta).close();
        verify(conexion).close();
    }
}
